#!/bin/bash
# Build the tvOS app with the credentials in ../xtream.properties and install it on the
# paired Apple TV. Usage: ./build-tv.sh [device-name]   (default: "Living Room")
set -euo pipefail
cd "$(dirname "$0")"
DEVICE="${1:-Living Room}"
PROPS=../xtream.properties
val() { grep "^$1=" "$PROPS" | cut -d= -f2- | tr -d ' \r'; }
# Baked-in credentials, generated on every build and never committed.
cat > StreamEverything/Sources/Credentials.swift <<SWIFT
// Generated by build-tv.sh from xtream.properties. Do not edit or commit.
enum Credentials {
    static let server = "$(val XTREAM_SERVER)"
    static let user = "$(val XTREAM_USER)"
    static let pass = "$(val XTREAM_PASS)"
    static let tmdbKey = "$(val TMDB_KEY)"
    static let watchmodeKey = "$(val WATCHMODE_KEY)"
}
SWIFT
xcodegen generate --quiet
xcodebuild -project StreamEverything.xcodeproj -scheme StreamEverything -configuration Release \
  -destination "platform=tvOS,name=$DEVICE" -derivedDataPath build \
  -allowProvisioningUpdates -allowProvisioningDeviceRegistration -quiet build
APP=build/Build/Products/Release-appletvos/StreamEverything.app
echo "built: $(pwd)/$APP"
xcrun devicectl device install app --device "$DEVICE" "$APP"
xcrun devicectl device process launch --device "$DEVICE" com.nirajgtm.xtreamtv.tv || true
